"""[clients]: trusted proxy networks (docs/ratelimit.md, section 3)."""

import ipaddress

from frontdoor.config import values
from frontdoor.errors import ConfigError


def parse_network(text, what: str):
    """A CIDR network (or single address) as an ip_network; IPv4-mapped IPv6 becomes IPv4."""
    if not isinstance(text, str) or "%" in text or text != text.strip():
        raise ConfigError(f"{what}: not a network: {text!r}")
    try:
        net = ipaddress.ip_network(text, strict=True)
    except ValueError:
        raise ConfigError(f"{what}: not a network: {text!r}") from None
    if net.version == 6 and net.prefixlen >= 96 and net.network_address.ipv4_mapped is not None:
        net = ipaddress.ip_network(
            (net.network_address.ipv4_mapped, net.prefixlen - 96), strict=True)
    return net


def network_list(t: dict, key: str, what: str) -> tuple:
    v = t[key]
    if not isinstance(v, list) or not all(isinstance(x, str) for x in v):
        raise ConfigError(f"{what}: {key} must be a list of strings")
    return tuple(parse_network(x, f"{what}: {key}") for x in v)


def parse(value) -> tuple:
    t = values.table(value, "clients")
    values.only_keys(t, ["trusted_proxies"], "clients")
    if "trusted_proxies" not in t:
        return ()
    return network_list(t, "trusted_proxies", "clients")
