"""Stage 3: rate limiting (docs/ratelimit.md)."""

from fractions import Fraction

from frontdoor.http.addresses import client_address, in_any, key_text

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit", [])
        self.trusted = config.section("clients", ())
        self.now = None
        self.buckets = {}
        self.refused = {lim.name: 0 for lim in self.limits}


def setup(config):
    return State(config)


def _ceil_div(x: Fraction, d: int) -> int:
    return -((-x) // d)


def _key_value(part, ctx, addr):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return key_text(addr)
