import re
from dataclasses import dataclass

from frontdoor.config import values
from frontdoor.config.clients import network_list
from frontdoor.errors import ConfigError

KEYS = ["name", "algorithm", "rate", "per", "burst", "key", "routes", "methods", "cost", "exempt"]
PARTS = ("tenant", "client", "route", "method")
_PER = re.compile(r"([0-9]+)(ms|s|m|h)")
_UNIT_MS = {"ms": 1, "s": 1000, "m": 60000, "h": 3600000}


@dataclass(frozen=True)
class Limit:
    name: str
    algorithm: str
    rate: int
    per_ms: int
    capacity: int
    key: tuple
    routes: frozenset | None
    methods: frozenset | None
    cost: dict
    exempt: tuple

    @property
    def window(self) -> bool:
        return self.algorithm == "fixed-window"


def _per(t, what):
    text = values.string(t, "per", what)
    m = _PER.fullmatch(text)
    if not m or int(m.group(1)) == 0:
        raise ConfigError(f"{what}: per is not a valid duration: {text!r}")
    return int(m.group(1)) * _UNIT_MS[m.group(2)]


def _key(t, what):
    parts = values.string_list(t, "key", what)
    seen = set()
    out = []
    for p in parts:
        if p in PARTS:
            norm = p
        elif p.startswith("header:") and p[7:]:
            norm = "header:" + p[7:].lower()
        else:
            raise ConfigError(f"{what}: unknown key part {p!r}")
        if norm in seen:
            raise ConfigError(f"{what}: key part {p!r} appears twice")
        seen.add(norm)
        out.append(p if p in PARTS else "header:" + p[7:])
    return tuple(out)


def _cost(t, what):
    if "cost" not in t:
        return {}
    c = values.table(t["cost"], f"{what}: cost")
    out = {}
    for m, v in c.items():
        if not isinstance(v, int) or isinstance(v, bool) or v < 1:
            raise ConfigError(f"{what}: cost of {m} must be a positive integer")
        if m.upper() in out:
            raise ConfigError(f"{what}: cost for {m.upper()} given twice")
        out[m.upper()] = v
    return out


def parse(value) -> list:
    out = []
    names = set()
    for i, t in enumerate(values.tables(value, "limit"), 1):
        what = f"limit {i}"
        values.only_keys(t, KEYS, what)
        name = values.string(t, "name", what)
        what = f"limit {name}"
        if name in names:
            raise ConfigError(f"limit name {name!r} is used twice")
        names.add(name)
        algo = t.get("algorithm", "token-bucket")
        if algo not in ("token-bucket", "fixed-window"):
            raise ConfigError(f"{what}: unknown algorithm {algo!r}")
        rate = values.positive_int(t, "rate", what)
        per_ms = _per(t, what)
        if algo == "fixed-window":
            if "burst" in t:
                raise ConfigError(f"{what}: burst is only for token-bucket")
            capacity = rate
        else:
            capacity = values.positive_int(t, "burst", what, required=False, missing=rate)
        key = _key(t, what)
        routes = values.string_list(t, "routes", what, required=False)
        methods = values.string_list(t, "methods", what, required=False)
        exempt = network_list(t, "exempt", what) if "exempt" in t else ()
        out.append(Limit(name, algo, rate, per_ms, capacity, key,
                         frozenset(routes) if routes is not None else None,
                         frozenset(m.upper() for m in methods) if methods is not None else None,
                         _cost(t, what), exempt))
    return out


def check_routes(config) -> None:
    known = {r.name for r in config.routes}
    for lim in config.section("limit", []):
        for r in sorted(lim.routes or ()):
            if r not in known:
                raise ConfigError(f"limit {lim.name}: unknown route {r!r}")
