"""Client addresses as the rate limiter sees them (docs/ratelimit.md, section 7)."""

import ipaddress
import re

_PORT = re.compile(r"[0-9]{1,5}")


def parse_address(text: str):
    """An ip_address from an entry (optional port, brackets for IPv6), or None. Mapped IPv4 becomes IPv4."""
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        rest = text[end + 1:]
        if rest and not (rest.startswith(":") and _PORT.fullmatch(rest[1:])):
            return None
        host = text[1:end]
        if ":" not in host:
            return None
    else:
        host = text
        if host.count(":") == 1:
            host, port = host.split(":")
            if not _PORT.fullmatch(port):
                return None
    if not host or "%" in host or host != host.strip():
        return None
    try:
        addr = ipaddress.ip_address(host)
    except ValueError:
        return None
    if addr.version == 6 and addr.ipv4_mapped is not None:
        addr = addr.ipv4_mapped
    return addr


def in_any(addr, networks) -> bool:
    return any(addr.version == n.version and addr in n for n in networks)


def client_address(request, trusted):
    """The client address (an ip_address), or the peer's text when it is not an address."""
    peer = parse_address(request.peer)
    if peer is None:
        return request.peer
    if not in_any(peer, trusted):
        return peer
    entries = [e.strip(" \t") for v in request.headers.get_all("X-Forwarded-For") for e in v.split(",")]
    if not entries:
        return peer
    parsed = [parse_address(e) for e in entries]
    for i in range(len(entries) - 1, -1, -1):
        a = parsed[i]
        if a is None:
            return parsed[i + 1] if i + 1 < len(entries) else peer
        if not in_any(a, trusted):
            return a
    return parsed[0]


def key_text(addr) -> str:
    if isinstance(addr, str):
        return addr
    if addr.version == 6:
        return str(ipaddress.ip_network((addr, 64), strict=False))
    return str(addr)
